import csv
import io


def parse_csv(raw_csv: str):
    previous_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(max(previous_limit, 2147483647))
        records = list(csv.reader(io.StringIO(raw_csv, newline="")))
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    if columns:
        columns[0] = columns[0].removeprefix("\ufeff")

    rows = records[1:]
    width = max([len(columns)] + [len(row) for row in rows])
    used = set(columns)

    while len(columns) < width:
        index = len(columns) + 1
        name = "column_{}".format(index)
        suffix = 2
        while name in used:
            name = "column_{}_{}".format(index, suffix)
            suffix += 1
        columns.append(name)
        used.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
